-basis:84px}.hx-fit2 .hx-ring svg{max-width:84px}.hx-fit2 .hx-ring span{display:none}.hx-fit2 .hx-ring b{font-size:11px}.hx-none{padding:18px 4px;font-size:13px;opacity:.7}@media (max-width:620px){.hx-r{grid-template-columns:1fr}.hx-seg{grid-column:1}.hx-title{font-size:19px}.hx-kv{font-size:20px}}
.hx-pills { display: flex; flex-wrap: wrap; gap: 6px; margin: 6px 0 4px; min-height: 0 }
.hx-pills:empty { display: none }
.hx-pill { display: inline-flex; align-items: center; gap: 7px; padding: 3px 9px; border-radius: 6px; font-size: 11px; line-height: 16px; white-space: nowrap; border: 1px solid rgba(204, 204, 220, .15); background: rgba(204, 204, 220, .04); color: inherit; transition: transform .2s ease, box-shadow .3s ease; cursor: default }
