.hx-pill i { width: 7px; height: 7px; border-radius: 50%; background: #8e8e8e; flex-shrink: 0 }
.hx-pill b { font-size: 9.5px; font-weight: 800; letter-spacing: 1px; text-transform: uppercase; opacity: .95 }
