.hx-pill[data-s="ok"] i { background: #73BF69; box-shadow: 0 0 6px rgba(115, 191, 105, .6) }
.hx-pill[data-s="ok"] b { color: #73BF69 }
.hx-pill[data-s="warn"] { border-color: rgba(255, 152, 48, .32); background: rgba(255, 152, 48, .08) }
.hx-pill[data-s="warn"] i { background: #FF9830; box-shadow: 0 0 6px rgba(255, 152, 48, .6) }
.hx-pill[data-s="warn"] b { color: #FF9830 }
.hx-pill[data-s="bad"] { border-color: rgba(242, 73, 92, .38); background: rgba(242, 73, 92, .09) }
