// KES Rotation Timeline: Key Life, Rotation Window, Opcert: afterRender JS
(function () {
  var ROOT_ID = 'hx-rotation';
  try {

  function fhref(x) { var u = new URLSearchParams(window.location.search); return '/d/dingo-forging?var-pod=' + encodeURIComponent(x.pod) + '&var-network=' + encodeURIComponent(x.net) + '&from=' + encodeURIComponent(u.get('from') || 'now-6h') + '&to=' + encodeURIComponent(u.get('to') || 'now') }
  var s = (context && context.panelData && context.panelData.series) ? context.panelData.series : [];
  function lastv(v) { if (!v) return undefined; for (var i = v.length - 1; i >= 0; i--) { var x = v[i]; if (x !== null && x !== undefined && isFinite(x)) return Number(x) } return undefined }
  /* rows(ref): [{l: labels, v: last value}] for every series of that query */
  /* two namespaces can both run relay-0: a pod name seen in more than one namespace is keyed and shown as namespace/pod; podRaw keeps the bare name */
  var podNs = {};
  for (var sn = 0; sn < s.length; sn++) {
    var fn = (s[sn] && s[sn].fields) || [];
    for (var jn = 0; jn < fn.length; jn++) {
      var lbn = fn[jn].labels;
      if (lbn && lbn.pod && lbn.namespace) { var qn = podNs[lbn.pod] = podNs[lbn.pod] || {}; qn[lbn.namespace] = 1 }
    }
  }
  function podId(lb) {
    var o = {}; for (var k in lb) o[k] = lb[k];
    if (lb.pod) { o.podRaw = lb.pod; var q = podNs[lb.pod]; if (q && lb.namespace && Object.keys(q).length > 1) o.pod = lb.namespace + '/' + lb.pod }
    return o;
  }
  function rows(ref) {
    var out = [];
    for (var si = 0; si < s.length; si++) {
      if (!s[si] || s[si].refId !== ref) continue;
      var f = s[si].fields || [];
      for (var j = 0; j < f.length; j++) {
        if (f[j].type !== 'number') continue;
        var v = lastv(f[j].values && f[j].values.toArray ? f[j].values.toArray() : f[j].values);
        if (v !== undefined) out.push({ l: podId(f[j].labels || {}), v: v });
      }
    }
    return out;
  }
  function one(ref) { var r = rows(ref); return r.length ? r[0].v : undefined }
  function sum(ref) { var r = rows(ref), t = 0; for (var i = 0; i < r.length; i++) t += r[i].v; return r.length ? t : undefined }
  function minRow(r) { var m = null; for (var i = 0; i < r.length; i++) if (!m || r[i].v < m.v) m = r[i]; return m }
  function maxRow(r) { var m = null; for (var i = 0; i < r.length; i++) if (!m || r[i].v > m.v) m = r[i]; return m }
  function byLabel(ref, label) { var r = rows(ref), o = {}; for (var i = 0; i < r.length; i++) { var k = r[i].l[label]; if (k !== undefined) o[k] = r[i].v } return o }
  function has(x) { return x !== undefined && x !== null && isFinite(x) }
  function n0(x) { return has(x) ? String(Math.round(x)) : '–' }
  function ms(sec) { if (!has(sec)) return '–'; var m = sec * 1000; return m >= 10000 ? (m / 1000).toFixed(1) + ' s' : (m >= 100 ? Math.round(m) : (m >= 10 ? m.toFixed(0) : m.toFixed(1))) + ' ms' }
  function plural(n, one_, many) { return n + ' ' + (n === 1 ? one_ : many) }
  function names(a, max) { max = max || 3; return a.length <= max ? a.join(', ') : a.slice(0, max).join(', ') + ' +' + (a.length - max) }
  function esc(t) { return String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;') }
  var RANK = { na: 0, ok: 1, warn: 2, bad: 3 };
  function worst(a, b) { return RANK[b] > RANK[a] ? b : a }
  /* lower is better: ok under w, warn under b, else bad */
  function low(x, w, b) { return !has(x) ? 'na' : (x < w ? 'ok' : (x < b ? 'warn' : 'bad')) }
  /* higher is better: ok at or above g, warn at or above a, else bad */
  function high(x, g, a) { return !has(x) ? 'na' : (x >= g ? 'ok' : (x >= a ? 'warn' : 'bad')) }
  function el(id) { return document.getElementById(id) }
  var root = el(ROOT_ID);
  /* light theme: ask Grafana, else infer it from the inherited text colour (dark text = light theme) */
  try {
    var th = context.grafana && context.grafana.theme, light = null;
    if (th && typeof th.isDark === 'boolean') light = !th.isDark;
    if (light === null && root && typeof getComputedStyle === 'function') {
      var m = /(\d+)[, ]+(\d+)[, ]+(\d+)/.exec(getComputedStyle(root).color || '');
      if (m) light = (0.299 * m[1] + 0.587 * m[2] + 0.114 * m[3]) < 128;
    }
    if (root && light && String(root.className).indexOf('hx-light') < 0) root.className += ' hx-light';
  } catch (e) { }
  /* fit(): a dynamic-text panel scrolls inside itself when its content is taller than the panel, and that
     captures the page scroll. Find the scrolling ancestor and, while the content overflows it, step through the
     compact levels (hx-fit1 drops the detail line, hx-fit2 also thins the rows and drops the legend). */
  function fit() {
    try {
      if (!root || !root.parentElement || typeof getComputedStyle !== 'function') return;
      root.className = String(root.className).replace(/ hx-fit\d/g, '');
      var box = root.parentElement, found = false;
      /* only a scroller inside this panel counts: stop at the panel chrome (<section>) or the grid item */
      while (box && box !== document.body) {
        var cls = typeof box.className === 'string' ? box.className : '';
        if (box.tagName === 'SECTION' || cls.indexOf('react-grid-item') >= 0) break;
        var oy = getComputedStyle(box).overflowY;
        if ((oy === 'auto' || oy === 'scroll') && box.clientHeight > 0) { found = true; break }
        box = box.parentElement;
      }
      if (!found) return;
      for (var lvl = 1; lvl <= 2 && box.scrollHeight > box.clientHeight + 1; lvl++) root.className += ' hx-fit' + lvl;
    } catch (e) { }
  }
  function dur(sec) { if (!has(sec)) return '–'; var a = Math.abs(sec); if (a < 90) return Math.round(a) + ' s'; if (a < 5400) return Math.round(a / 60) + ' min'; if (a < 172800) return (a / 3600).toFixed(a < 36000 ? 1 : 0) + ' h'; return (a / 86400).toFixed(a < 864000 ? 1 : 0) + ' d' }
  var overall = 'na';
  /* kpi(key, value, unit, status, note): fill one tile; value '–' when undefined */
  function kpi(key, value, unit, status, note) {
    var t = el(ROOT_ID + '-k-' + key); if (!t) return;
    var miss = value === undefined || value === null || value === '–';
    var st = miss ? 'na' : (status || 'na');
    t.setAttribute('data-s', st);
    var c = t.children;
    if (c[1]) c[1].innerHTML = miss ? '–' : esc(value) + (unit ? '<small>' + esc(unit) + '</small>' : '');
    if (c[2]) c[2].textContent = miss ? (note || 'no data') : (note || '');
    if (c[2]) c[2].title = miss ? '' : (note || '');
    overall = worst(overall, st);
  }
  var BADGE = { ok: 'Healthy', warn: 'Attention', bad: 'Action needed', na: 'No data' };
  function verdict(html, status) {
    var st = status || overall;
    if (root) root.setAttribute('data-s', st);
    var b = el(ROOT_ID + '-badge'); if (b) b.lastChild.textContent = BADGE[st];
    var v = el(ROOT_ID + '-verdict'); if (v) v.innerHTML = html;
    fit();
  }

  var RENEW = 8;
  var out = el(ROOT_ID + '-rows'); if (!out) return;
  var st = rows('ST'), EX = byLabel('EX', 'pod'), CUR = byLabel('CUR', 'pod'), SPK = byLabel('SPK', 'pod');
  var OL = byLabel('OL', 'pod'), OC = byLabel('OC', 'pod'), RL = byLabel('RL', 'pod'), RF = byLabel('RF', 'pod');
  var list = [], life = 0;
  for (var i = 0; i < st.length; i++) {
    var a = st[i].l.pod; if (!a || !has(EX[a]) || !has(CUR[a])) continue;
    var o = { name: a, pod: st[i].l.podRaw || st[i].l.pod || '', net: st[i].l.cardano_network || '', sub: st[i].l.cardano_network || '', start: st[i].v, end: EX[a], cur: CUR[a], days: (has(SPK[a]) ? SPK[a] : 129600) / 86400, ol: OL[a], oc: OC[a], rl: RL[a], rf: RF[a] };
    o.life = Math.max(1, o.end - o.start); o.left = o.end - o.cur; life = Math.max(life, o.life); list.push(o);
  }
  list.sort(function (x, y) { return x.left - y.left });
  if (!life) life = 62;
  var AL = byLabel('AL', 'profile'), AC = byLabel('AC', 'profile'), AI = byLabel('AI', 'profile'), AD = byLabel('AD', 'profile'), agent = [];
  for (var p in AL) { if (!has(AC[p])) continue; agent.push({ name: p, sub: 'KES agent key', agent: true, end: AL[p], cur: AC[p], left: AL[p] - AC[p], life: Math.max(life, AL[p] - AC[p]), days: 1.5, ol: AI[p], split: has(AD[p]) }) }
  agent.sort(function (x, y) { return x.left - y.left });
  var all = list.concat(agent);
  if (!all.length) { out.innerHTML = '<div class="hx-none">No producer reports an operational certificate in this time range.</div>'; return }
  var h = '';
  for (var r = 0; r < all.length; r++) {
    var x = all[r], used = Math.min(1, Math.max(0, (x.life - x.left) / x.life)), win = Math.min(1, RENEW / x.life);
    var status = x.left > RENEW ? 'ok' : (x.left >= 4 ? 'warn' : 'bad'), col = status === 'ok' ? 'var(--ok)' : (status === 'warn' ? 'var(--warn)' : 'var(--bad)');
    var bar = '<u style="width:' + (used * 100).toFixed(2) + '%;background:rgba(128,136,150,.38)" title="KES periods already used"></u>' +
      '<u style="width:' + (Math.max(0, 1 - used) * 100).toFixed(2) + '%;background:' + col + ';opacity:.8" title="KES periods left"></u>' +
      '<u style="position:absolute;right:0;top:0;width:' + (win * 100).toFixed(2) + '%;background:repeating-linear-gradient(135deg,rgba(245,177,46,.95) 0 4px,rgba(245,177,46,.25) 4px 8px)" title="reference window: the default renewBeforePeriods is ' + RENEW + '; only rotation mode Auto renews, MonitorOnly never does"></u>' +
      '<em style="left:calc(' + (used * 100).toFixed(2) + '% - 1px)" title="now"></em>';
    var dLeft = x.left * x.days, dRot = (x.left - RENEW) * x.days, parts = [];
    parts.push(x.left > RENEW ? 'reference renewal point (' + RENEW + ' periods left) in about <b>' + n0(dRot) + ' days</b>' : (x.left > 0 ? '<b style="color:var(--warn)">inside the reference window: check the DingoNode rotation mode</b>' : '<b style="color:var(--bad)">EXPIRED</b>'));
    if (x.agent) {
      parts.push('opcert #' + n0(x.ol));
      parts.push('signable through KES period ' + n0(x.end) + ', now ' + n0(x.cur));
      parts.push(x.split ? '<b style="color:var(--bad)">replicas disagree on this key</b>' : 'replicas hold the same key');
    } else {
      if (has(x.ol) && has(x.oc)) parts.push(x.ol === x.oc ? 'opcert #' + n0(x.ol) + ' loaded, same on chain' : (x.ol > x.oc ? 'opcert #' + n0(x.ol) + ' loaded, chain has seen #' + n0(x.oc) + ' (new certificate, not yet used in a block)' : '<b style="color:var(--bad)">opcert #' + n0(x.ol) + ' loaded is behind #' + n0(x.oc) + ' on chain: its blocks are rejected</b>'));
      parts.push('KES periods ' + n0(x.start) + ' to ' + n0(x.end) + ', now ' + n0(x.cur));
      var nrl = has(x.rl) ? Math.round(x.rl) : 0, nrf = has(x.rf) ? Math.round(x.rf) : 0;
      parts.push(nrl ? plural(nrl, 'credential reload', 'credential reloads') + ' applied in this range' : 'no reload in this range');
      if (nrf) parts.push('<b style="color:var(--bad)">' + plural(nrf, 'reload', 'reloads') + ' failed</b>');
    }
    var tip = parts.join(' · ').replace(/<[^>]+>/g, '');
    h += '<div class="hx-r" title="' + esc(x.name + ': ' + tip) + '"' + (r === 0 ? ' style="border-top:0"' : '') + '><div class="hx-rn"><b>' + (x.pod ? '<a href="' + esc(fhref(x)) + '" style="color:inherit;text-decoration:none" title="Open in Forging Health">' + esc(x.name) + '</a>' : esc(x.name)) + '</b><span>' + esc(x.sub) + '</span></div>' +
      '<div><div class="hx-bar">' + bar + '</div></div>' +
      '<div class="hx-rv" data-s="' + status + '"><b>' + plural(Math.round(x.left), 'period', 'periods') + '</b> ' + n0(dLeft) + ' days left</div>' +
      '<div class="hx-seg"><span>' + parts.join('</span><span>') + '</span></div></div>';
  }
  out.innerHTML = h;
  fit();

  } catch (e) {
    var v = document.getElementById(ROOT_ID + '-rows');
    if (v) v.textContent = 'Panel script error: ' + (e && e.message ? e.message : e);
  }
})();
